#!/usr/bin/env python3
"""Generates 00_preflight_072_to_075_readonly.sql from the repository signature built on PostgreSQL 17 (001..072).
The preflight is READ ONLY (one read-only transaction, rolled back) and prints one row per gate:
  GATE | <name> | PASS / STOP / WARN / INFO | <detail>
"""
import os, re
HERE = os.path.dirname(os.path.abspath(__file__))
REPO = os.path.abspath(os.path.join(HERE, '..', '..', '..'))
exp = [l.rstrip('\n') for l in open(os.path.join(REPO, 'supabase/release/staging-073/expected-072-signature.txt')) if l.strip()]
sig_sql = open(os.path.join(REPO, 'supabase/release/staging-073/signature.sql')).read()
sig_sql = re.sub(r'^\s*--.*$', '', sig_sql, flags=re.M).strip().rstrip(';')
inner = sig_sql[sig_sql.index('from (') + len('from ('):sig_sql.rindex(') x')]
q = lambda s: "'" + s.replace("'", "''") + "'"
obj_rows = ',\n'.join('  (' + q(l) + ')' for l in exp if not l.startswith('H '))
h_rows = ',\n'.join('  (' + q(re.match(r'H (.+) [0-9a-f]{32}$', l).group(1)) + ', ' + q(l[-32:]) + ')' for l in exp if l.startswith('H '))
versions = sorted(f[:14] for f in os.listdir(os.path.join(REPO, 'supabase/migrations')) if re.match(r'^\d{14}_.*\.sql$', f) and f[:14] <= '20260101000072')
ver_rows = ', '.join('(' + q(v) + ')' for v in versions)
sql = f"""-- GOLDIA PRODUCTION PREFLIGHT 072 -> 073 -> 074 -> 075 — READ ONLY. Generated by docs/releases/production-075/gen-preflight.py.
-- Nothing is written: one READ ONLY transaction, rolled back. Output: GATE | name | PASS/STOP/WARN/INFO | detail.
-- Any STOP = do not start the release. WARN = decide before the release window. INFO = recorded for the after-compare.
-- Run (PowerShell; password is asked by psql, never typed on the command line):
--   $env:PGOPTIONS='-c default_transaction_read_only=on'
--   psql "host=<prod pooler> port=5432 dbname=postgres user=postgres.vrozlllcaxinavzxueif sslmode=require" -X -v ON_ERROR_STOP=1 -A -t -F " | " -f docs/releases/production-075/00_preflight_072_to_075_readonly.sql > PREFLIGHT-075.txt
begin transaction read only;
set local statement_timeout = '120s';
set local lock_timeout = '3s';

with
expected_obj(line) as (values
{obj_rows}
),
expected_h(sig, h) as (values
{h_rows}
),
repo_versions(v) as (values {ver_rows}),
actual_obj as (
  select s as line from ({inner}) x where s not like 'H %'
),
actual_h as (
  select p.oid::regprocedure::text as sig, md5(p.prosrc) as h_raw, md5(replace(p.prosrc, chr(13), '')) as h_lf
    from pg_proc p
   where p.pronamespace = 'public'::regnamespace
     and not exists (select 1 from pg_depend d where d.classid = 'pg_proc'::regclass and d.objid = p.oid and d.deptype = 'e')
),
hist as (select version from supabase_migrations.schema_migrations),
h_judged as (
  select e.sig, case when a.sig is null then 'MISSING' when a.h_raw = e.h then 'identical' when a.h_lf = e.h then 'crlf_only' else 'DIFFERENT' end as status
    from expected_h e left join actual_h a on a.sig = e.sig
),
gates(ord, name, result, detail) as (
  -- 1. identity
  select 10, 'not_jfs_demo', case when to_regprocedure('public.deployment_environment()') is null then 'PASS' else 'STOP' end,
         'deployment_environment() ' || case when to_regprocedure('public.deployment_environment()') is null then 'absent' else 'PRESENT (JFS demo database)' end
  union all select 11, 'server_version', case when current_setting('server_version_num')::int / 10000 = 17 then 'PASS' else 'WARN' end, current_setting('server_version')
  union all select 12, 'session_read_only', case when current_setting('transaction_read_only') = 'on' then 'PASS' else 'STOP' end, 'transaction_read_only=' || current_setting('transaction_read_only')
  union all select 13, 'organizations', 'INFO', (select count(*)::text from public.organizations)
  -- 2. migration history
  union all select 20, 'history_072_recorded', case when exists (select 1 from hist where version = '20260101000072') then 'PASS' else 'STOP' end, 'latest=' || coalesce((select max(version) from hist), '-')
  union all select 21, 'history_nothing_after_072', case when not exists (select 1 from hist where version > '20260101000072') then 'PASS' else 'STOP' end,
         coalesce((select string_agg(version, ',') from hist where version > '20260101000072'), 'none')
  union all select 22, 'history_repo_001_072_recorded', case when not exists (select 1 from repo_versions r where r.v not in (select version from hist)) then 'PASS' else 'WARN' end,
         'missing: ' || coalesce((select string_agg(v, ',') from repo_versions r where r.v not in (select version from hist)), 'none')
  -- 3. schema parity with repository 001..072 (functions, columns, policies, triggers, RLS)
  union all select 30, 'schema_objects_missing', case when not exists (select 1 from expected_obj e where e.line not in (select line from actual_obj)) then 'PASS' else 'STOP' end,
         (select count(*)::text from expected_obj e where e.line not in (select line from actual_obj)) || ' missing; first: ' ||
         coalesce((select string_agg(line, ' ; ') from (select line from expected_obj e where e.line not in (select line from actual_obj) order by 1 limit 5) z), '-')
  union all select 31, 'schema_objects_extra', 'INFO', (select count(*)::text from actual_obj a where a.line not in (select line from expected_obj)) || ' extra (kept)'
  union all select 32, 'function_bodies_identical', 'INFO', (select count(*)::text from h_judged where status = 'identical')
  union all select 33, 'function_bodies_crlf_only', case when exists (select 1 from h_judged where status = 'crlf_only') then 'INFO' else 'PASS' end,
         (select count(*)::text from h_judged where status = 'crlf_only') || ' (differ only by \\r from a Windows checkout; no behavioural effect)'
  union all select 34, 'function_bodies_DIFFERENT', case when not exists (select 1 from h_judged where status in ('DIFFERENT', 'MISSING')) then 'PASS' else 'STOP' end,
         coalesce((select string_agg(status || ' ' || sig, ' ; ') from (select * from h_judged where status in ('DIFFERENT', 'MISSING') order by sig limit 20) z), 'none')
  -- 4. data preconditions of 073 / 074 / 075
  union all select 40, '075_no_duplicate_code_in_org', case when not exists (select 1 from public.customers group by organization_id, customer_code having count(*) > 1) then 'PASS' else 'STOP' end,
         (select count(*)::text from (select 1 from public.customers group by organization_id, customer_code having count(*) > 1) d) || ' duplicate (organization_id, customer_code) groups'
  union all select 41, '075_global_code_unique_today', case when exists (select 1 from pg_constraint where conrelid = 'public.customers'::regclass and conname = 'customers_customer_code_key') then 'PASS' else 'WARN' end,
         'customers_customer_code_key ' || case when exists (select 1 from pg_constraint where conrelid = 'public.customers'::regclass and conname = 'customers_customer_code_key') then 'present' else 'ABSENT' end
  union all select 42, '075_customers_without_org', case when exists (select 1 from public.customers where organization_id is null) then 'WARN' else 'PASS' end,
         (select count(*)::text from public.customers where organization_id is null) || ' customers with organization_id NULL (stay unique among themselves)'
  union all select 43, '075_long_or_odd_codes', 'INFO',
         (select count(*)::text from public.customers where length(regexp_replace(customer_code, '\\D', '', 'g')) > 9) || ' codes with >9 digits (F-STG-1 trigger: customer creation already fails if >0); ' ||
         (select count(*)::text from public.customers where customer_code !~ '^CUST-[0-9]{{1,9}}$') || ' non-canonical codes (kept, ignored by the new numbering)'
  union all select 44, '075_rpc_create_customer_today', 'INFO',
         case when exists (select 1 from public.customers where length(regexp_replace(customer_code, '\\D', '', 'g')) > 9) then 'BROKEN for every organization (integer overflow) until 075' else 'works today (no long code yet)' end
  union all select 45, '075_customers_direct_insert_today', 'INFO',
         'authenticated INSERT=' || has_table_privilege('authenticated', 'public.customers', 'INSERT')::text || ', anon SELECT=' || has_table_privilege('anon', 'public.customers', 'SELECT')::text
  union all select 46, '075_factory_settings_one_row_per_org', case when not exists (select 1 from public.organization_factory_settings group by organization_id having count(*) > 1) then 'PASS' else 'STOP' end,
         (select count(*)::text from public.organization_factory_settings) || ' rows'
  union all select 47, '074_models_without_org', 'INFO', (select count(*)::text from public.jewelry_models where organization_id is null) || ' jewelry_models with NULL organization (read-only shared after 074)'
  union all select 48, '074_loss_configs_without_org', 'INFO', (select count(*)::text from public.stage_loss_configs where organization_id is null) || ' stage_loss_configs with NULL organization'
  union all select 49, '074_rows_of_unknown_org', case when exists (select 1 from public.jewelry_models m where m.organization_id is not null and not exists (select 1 from public.organizations o where o.id = m.organization_id)) then 'WARN' else 'PASS' end,
         (select count(*)::text from public.jewelry_models m where m.organization_id is not null and not exists (select 1 from public.organizations o where o.id = m.organization_id)) || ' models of a non-existent organization'
  union all select 50, '073_open_weight_sales_without_allocation', 'INFO',
         (select count(*)::text from public.jewelry_sales s where s.sale_type = 'weight' and s.status not in ('reversed', 'cancelled') and not exists (select 1 from public.weight_sale_allocations a where a.sale_id = s.id)) || ' (pre-068 history; reversals keep the 068 fallback)'
  -- 5. activity (release needs a quiet window)
  union all select 60, 'other_sessions', 'INFO', (select count(*)::text from pg_stat_activity where datname = current_database() and pid <> pg_backend_pid() and backend_type = 'client backend')
  union all select 61, 'idle_in_transaction', case when exists (select 1 from pg_stat_activity where datname = current_database() and pid <> pg_backend_pid() and state like 'idle in transaction%') then 'WARN' else 'PASS' end,
         (select count(*)::text from pg_stat_activity where datname = current_database() and pid <> pg_backend_pid() and state like 'idle in transaction%')
  union all select 62, 'long_running_queries_over_60s', case when exists (select 1 from pg_stat_activity where datname = current_database() and pid <> pg_backend_pid() and state = 'active' and now() - query_start > interval '60 seconds') then 'WARN' else 'PASS' end,
         (select count(*)::text from pg_stat_activity where datname = current_database() and pid <> pg_backend_pid() and state = 'active' and now() - query_start > interval '60 seconds')
  union all select 63, 'locks_on_sales_tables', case when exists (select 1 from pg_locks l join pg_class c on c.oid = l.relation where c.relname in ('customers', 'jewelry_sales', 'gold_settlements', 'consignment_pieces', 'seller_gold_accounts') and l.pid <> pg_backend_pid() and l.mode in ('AccessExclusiveLock', 'ExclusiveLock', 'ShareRowExclusiveLock')) then 'WARN' else 'PASS' end, 'strong locks held by other sessions'
  -- 6. snapshot for the after-compare (aggregates only, no customer data)
  union all select 70, 'snapshot_counts', 'INFO',
         'customers=' || (select count(*) from public.customers) || ' sales=' || (select count(*) from public.jewelry_sales) || ' settlements=' || (select count(*) from public.gold_settlements)
         || ' receipts=' || (select count(*) from public.factory_receipts) || ' pieces=' || (select count(*) from public.consignment_pieces) || ' employees=' || (select count(*) from public.employees)
  union all select 71, 'snapshot_balances', 'INFO',
         'client_debt_g=' || (select coalesce(sum(current_debt_grams), 0) from public.client_gold_accounts) || ' client_advance_g=' || (select coalesce(sum(advance_balance_grams), 0) from public.client_gold_accounts)
         || ' seller_owes_g=' || (select coalesce(sum(seller_owes_manager_g), 0) from public.seller_gold_accounts) || ' seller_stock_g=' || (select coalesce(sum(current_physical_stock_g), 0) from public.seller_gold_accounts)
         || ' vault_uzs=' || (select coalesce(sum(manager_cash_amount), 0) from public.manager_vault_account) || ' vault_usd=' || (select coalesce(sum(manager_usd_amount), 0) from public.manager_vault_account)
         || ' factory_obligation_g=' || (select coalesce(sum(current_factory_obligation_g), 0) from public.manager_vault_account)
)
select 'GATE', name, result, detail from gates
union all
select 'RESULT', 'preflight_072_to_075', case when exists (select 1 from gates where result = 'STOP') then 'STOP' when exists (select 1 from gates where result = 'WARN') then 'WARN' else 'PASS' end,
       (select count(*) from gates where result = 'STOP') || ' STOP, ' || (select count(*) from gates where result = 'WARN') || ' WARN'
order by 1 desc, 2;

rollback;
"""
open(os.path.join(HERE, '00_preflight_072_to_075_readonly.sql'), 'w').write(sql)
print('written', len(sql), 'bytes')
